# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
```

## Basic Pool Setup

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                    // Maximum connections in pool
  min: 2,                     // Minimum idle connections maintained
  idleTimeoutMillis: 30000,   // Remove idle connections after 30s
  connectionTimeoutMillis: 5000, // Fail if can't connect within 5s

  // Query timeout (requires pg >= 8.x)
  statement_timeout: 10000,   // Kill queries running over 10s
  query_timeout: 10000,       // Timeout for query execution

  // SSL (for production)
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true, ca: process.env.DB_SSL_CERT }
    : false,
});

module.exports = pool;
```

## Pool Event Handlers

```javascript
// db/pool.js (continued)
pool.on('connect', (client) => {
  console.log('New client connected to pool');
  // Set session-level settings on each new connection
  client.query('SET timezone = "UTC"');
});

pool.on('acquire', (client) => {
  // Fires when a client is checked out from the pool
  console.debug('Client acquired from pool');
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

pool.on('error', (err, client) => {
  // Handles unexpected errors on idle clients
  console.error('Unexpected error on idle client:', err.message);
  // Don't crash the server - pool will handle reconnection
});
```

## Query Wrapper with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

class DatabaseError extends Error {
  constructor(message, code, query) {
    super(message);
    this.name = 'DatabaseError';
    this.code = code;
    this.query = query;
  }
}

// Simple query - pool manages connection automatically
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    if (duration > 1000) {
      console.warn('Slow query detected:', { text, duration, rows: result.rowCount });
    }

    return result;
  } catch (err) {
    handleQueryError(err, text);
  }
}

function handleQueryError(err, queryText) {
  // Map PostgreSQL error codes to meaningful messages
  const errorMap = {
    '23505': 'Duplicate entry - record already exists',
    '23503': 'Referenced record does not exist',
    '23502': 'Required field is missing',
    '42P01': 'Database table not found',
    '28P01': 'Invalid database credentials',
    '3D000': 'Database does not exist',
    '57014': 'Query cancelled due to timeout',
    'ECONNREFUSED': 'Database server is unreachable',
    'ETIMEDOUT': 'Connection to database timed out',
  };

  const message = errorMap[err.code] || err.message;
  throw new DatabaseError(message, err.code, queryText);
}

module.exports = { query, DatabaseError };
```

## Transaction Helper

```javascript
// db/transaction.js
const pool = require('./pool');

async function withTransaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release(); // Always return client to pool
  }
}

// Usage example
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (client) => {
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );
    return { success: true };
  });
}

module.exports = { withTransaction };
```

## Pool Health Monitoring

```javascript
// db/health.js
const pool = require('./pool');

function getPoolStats() {
  return {
    total: pool.totalCount,       // All connections (idle + active)
    idle: pool.idleCount,         // Waiting for queries
    waiting: pool.waitingCount,   // Queued requests waiting for a connection
    active: pool.totalCount - pool.idleCount,
  };
}

async function healthCheck() {
  const stats = getPoolStats();

  // Warn if pool is under pressure
  if (stats.waiting > 5) {
    console.warn('Pool pressure detected:', stats);
  }

  try {
    const start = Date.now();
    await pool.query('SELECT 1');
    return {
      status: 'healthy',
      latency: Date.now() - start,
      pool: stats,
    };
  } catch (err) {
    return {
      status: 'unhealthy',
      error: err.message,
      pool: stats,
    };
  }
}

// Expose as an endpoint
async function healthRoute(req, res) {
  const health = await healthCheck();
  const statusCode = health.status === 'healthy' ? 200 : 503;
  res.status(statusCode).json(health);
}

module.exports = { getPoolStats, healthCheck, healthRoute };
```

## Graceful Shutdown

```javascript
// server.js
const pool = require('./db/pool');

async function shutdown(signal) {
  console.log(`Received ${signal}, shutting down gracefully...`);

  try {
    // Stop accepting new connections, drain existing ones
    await pool.end();
    console.log('Database pool closed');
    process.exit(0);
  } catch (err) {
    console.error('Error during shutdown:', err);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

## Environment Configuration

```bash
# .env
DB_HOST=localhost
DB_PORT=5432
DB_NAME=myapp
DB_USER=myapp_user
DB_PASSWORD=secret
DB_POOL_MAX=20
DB_POOL_MIN=2
NODE_ENV=development
```

## Key Configuration Guidelines

| Setting | Development | Production |
|---|---|---|
| `max` | 5–10 | 10–50 (tune to DB limits) |
| `min` | 0–2 | 2–5 |
| `idleTimeoutMillis` | 10,000 | 30,000 |
| `connectionTimeoutMillis` | 3,000 | 5,000 |
| `statement_timeout` | 30,000 | 10,000 |

**Critical rules:**
- Always `release()` clients in a `finally` block
- Never exceed `max_connections` on your PostgreSQL server (check with `SHOW max_connections`)
- Set `max` pool size to roughly `(max_connections / num_app_instances) - 5` as a safe buffer
- Use `pool.query()` for single queries; only use `pool.connect()` when you need transactions or multiple sequential queries on the same connection
